style.css:
@-moz-document domain("youtube.com"), domain("www.youtube.com") {
/* enforce dark-ish base so wallpapers don't wash out in light mode */
  html[dark], html:not([dark]) {
    color-scheme: dark !important;
    background-color: #000 !important;
  }

  /* make main containers transparent so wallpaper shows through */
  html, body, ytd-app, #page-manager, ytd-page-manager {
    background: transparent !important;
    color: #fff !important;
  }

  /* wallpaper layer (full screen) */
  html::before {
    content: "";
    position: fixed;
    inset: 0;
    z-index: 0;
    pointer-events: none;
    background-image: url("https://media.discordapp.net/attachments/1257819934407528621/1424618165765410930/fallen_angel_4k.jpg?ex=68e49a8e&is=68e3490e&hm=4296afede79d40642af81ed027e5b907728a12263e386a6babf1a5fe0ffcb681&=&format=webp&width=1121&height=711");
    background-repeat: no-repeat;
    background-size: cover;
    background-position: center center;
    background-attachment: fixed;
    transform: scale(1.02);
    filter: none;
  }

  /* subtle overlay so UI text/icons remain readable (change alpha to 0 for no overlay) */
  html::after {
    content: "";
    position: fixed;
    inset: 0;
    z-index: 1;
    pointer-events: none;
    background: rgba(0, 0, 0, 0.25);
  }

  /* keep YouTube UI above the wallpaper */
  ytd-app,
  #page-manager,
  ytd-page-manager,
  ytd-masthead-renderer,
  #content,
  #primary,
  #secondary,
  ytd-watch-flexy {
    position: relative;
    z-index: 2 !important;
    background: transparent !important;
    color: #fff !important;
  }

  /* sidebar & header lightly tinted for readability (remove or lower alpha to make fully transparent) */
  #guide,
  ytd-guide-renderer,
  #masthead-container,
  ytd-mini-guide-renderer,
  #related,
  #secondary {
    background: rgba(0, 0, 0, 0.18) !important;
    backdrop-filter: blur(2px);
  }

  /* keep the video player solid black so controls are visible */
  .html5-video-player,
  #player,
  ytd-player {
    background: #000 !important;
    z-index: 3 !important;
  }

  /* make dialogs/popups show above everything */
  ytd-popup-container,
  tp-yt-paper-dialog,
  ytd-dialog-renderer,
  ytd-popup-container * {
    z-index: 1000000 !important;
  }

  /* hide YouTube's default background layer if present */
  #background,
  ytd-browse[page-subtype="home"] #background {
    display: none !important;
  }

  /* mobile adjustments */
  @media (max-width: 900px) {
    html::before {
      transform: scale(1.06);
      filter: none;
    }
  }
}
